-- Upload-ready SQL for 5 completed generated posts

-- sql: 10000010001108-layflat
START TRANSACTION;
SET @existing_post=(SELECT ID FROM `ha_posts` WHERE `post_name`='زاویه-مرکزی-looleh-nakhi-tashoo' OR (`post_type`='arak' AND `post_title`='خرید لوله نخی و تاشو در زاویه') LIMIT 1);
SET @post_id=COALESCE(@existing_post,LAST_INSERT_ID());
COMMIT;


